import { Component, OnInit } from '@angular/core';
import {HomeService} from '../home.service'
// import {NavParams} from '@ionic/angular'
import {Router} from '@angular/router'
import { ModalController } from '@ionic/angular';
import { Email1Page } from '../email1/email1.page';
import {Location } from '@angular/common';
import num from '../data/k'
@Component({
  selector: 'app-emailform',
  templateUrl: './emailform.page.html',
  styleUrls: ['./emailform.page.scss'],
})
export class EmailformPage implements OnInit {
  t:{};
  public mf:string;
  detail:any;
  id:any;
  error = null
  constructor(private user:HomeService,private router:Router,private modalCtrl:ModalController, public _location: Location) {
    this.id=this.router.getCurrentNavigation().extras
    this.detail=this.id.id
  this.mf = num;
   }

  ngOnInit() {
    this.t=JSON.parse(localStorage.token)
  }
  validateEmail(email) {
   const regularExpression = /^(([^<>()\[\]\\.,;:\s@"]+(\.[^<>()\[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/;
   return regularExpression.test(String(email));
  }
async btnclick(email,emaill){
  var k=this.validateEmail(email)
  if(email==null){
    this.user.toast("Please enter email",'bottom',2000,'normalToast')
  }
  else if(k==false)
  {
    this.user.toast("Provide a valid email address",'bottom',2000,'normalToast')
  }
  else if(email!=emaill)
  {
this.user.toast("Entered emails doesn't match",'bottom',2000,'normalToast')
    this.router.navigateByUrl('/emailform');
  }
  else{
    this.user.emailForm(email,this.t,this.detail).subscribe((res:any)=>{
       if(res.m=="This email already exists"){
      this.user.toast("This email is already exists",'bottom',2000,'normalToast');
      this.router.navigateByUrl('/emailform');
      }
       if(res.m=="Failed to deliver the mail, Hemce the account not created. This may due to invalid email. Kindly provide a Valid email"){
       this.user.toast("Failed to deliver the mail, Hemce the account not created. This may due to invalid email. Kindly provide a Valid email",'bottom',2000,'normalToast')
       this.router.navigateByUrl('/emailform');
      }
       if(res.m=="Account already activated"){
        this.user.toast("This account is already activated",'bottom',2000,'noramlToast')
        this.router.navigateByUrl("/partydetails");
      }
      if(res.m=="Account created"){
       this.user.toast("Account created. The username and password are sent to the provided email",'bottom',2000,'noramlToast')
       if(localStorage.getItem('p')=='lokc')
       {this.router.navigateByUrl('/statepartylok');}
       else if(localStorage.getItem('p')=='rajc')
       {this.router.navigateByUrl('/partycandidates');}
       else if(localStorage.getItem('p')=='ac')
       {this.router.navigateByUrl('/statepartylok'); }
       else if(localStorage.getItem('p')=='cc')
       { this.router.navigateByUrl('/council');  }
       else if(localStorage.getItem('p')=='party' || localStorage.getItem('p')=='ll' || localStorage.getItem('p')=='rr'|| localStorage.getItem('p')=='aa'|| localStorage.getItem('p')=='ccc'){
    this.router.navigateByUrl('/choice');   }
       else {  this.router.navigateByUrl("/choice");  }
     }
    }, error => {
    //  alert("Check Internet connection")
      this.error = error.status  ;
      alert(error.status+"error")
    });
// alert("Refresh to find the changes") ;
}

}

}
